package main

import (
	"fmt"
	"time"
)

func main() {
	delays := []time.Duration{10, 10, 10, 10, 200}
	start := time.Now()
	ch := make(chan int, len(delays))
	for i, d := range delays {
		go func() {
			time.Sleep(d * time.Millisecond)
			ch <- i
		}()
	}
	<-ch
	fmt.Println("page ready after", time.Since(start).Round(50*time.Millisecond))
	for range len(delays) - 1 {
		<-ch
	}
	fmt.Println("all five replies after", time.Since(start).Round(50*time.Millisecond))
}
